import{_ as e,o as n,c as t,a2 as s}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"EIP-712 and EIP-3009: Why an Agent May Not Need Gas","description":"","frontmatter":{},"headers":[],"relativePath":"learn/02-agent-payments/gasless-eip-3009.md","filePath":"learn/02-agent-payments/gasless-eip-3009.md","lastUpdated":1792595354000}'),i={name:"learn/02-agent-payments/gasless-eip-3009.md"};function o(r,a,d,p,l,c){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="eip-712-and-eip-3009-why-an-agent-may-not-need-gas" tabindex="-1">EIP-712 and EIP-3009: Why an Agent May Not Need Gas <a class="header-anchor" href="#eip-712-and-eip-3009-why-an-agent-may-not-need-gas" aria-label="Permalink to &quot;EIP-712 and EIP-3009: Why an Agent May Not Need Gas&quot;">​</a></h1><h2 id="the-gas-problem" tabindex="-1">The gas problem <a class="header-anchor" href="#the-gas-problem" aria-label="Permalink to &quot;The gas problem&quot;">​</a></h2><p>On EVM networks, sending a transaction normally requires the sender to pay network fees in the chain&#39;s native gas token. That creates friction for an agent whose payment balance contains USDC but no ETH or other native token: before using a paid service, it would first need to acquire gas.</p><h2 id="authorization-can-be-relayed" tabindex="-1">Authorization can be relayed <a class="header-anchor" href="#authorization-can-be-relayed" aria-label="Permalink to &quot;Authorization can be relayed&quot;">​</a></h2><p>EIP-3009 defines USDC authorization methods such as <code>transferWithAuthorization</code>. The token holder signs structured authorization data off-chain; another party can submit it on-chain and pay the transaction fee. The holder can therefore authorize a transfer without personally submitting the transaction.</p><p>EIP-712 provides a structured-data signing format. Typed fields make the signed message easier for software and wallets to interpret than an opaque byte string. An authorization typically binds relevant values such as token domain, sender, recipient, amount, validity window, and a unique nonce. Exact fields depend on the token contract and method.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent validates payment terms</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Wallet signs bounded authorization</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Facilitator submits the authorization and pays gas</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Token contract verifies and performs transfer</span></span></code></pre></div><p>“Gasless” means the buyer need not pay gas for that transaction directly; the facilitator still pays network fees and may apply its own rules or costs.</p><h2 id="security-checks" tabindex="-1">Security checks <a class="header-anchor" href="#security-checks" aria-label="Permalink to &quot;Security checks&quot;">​</a></h2><p>Before signing, verify chain, token contract, recipient, amount, expiry, and nonce. Keep the private key outside the model&#39;s context and avoid granting broad approvals. The signer should sign only data that has already passed independent spending policy.</p><p>Authorization is not the same as confirmed settlement. Relayed submission can fail, remain pending, or have an uncertain result. Track the authorization and settlement state, and do not blindly sign a second transfer after a timeout. Use test networks and test tokens while developing.</p>`,11)])])}const g=e(i,[["render",o]]);export{u as __pageData,g as default};
